/* XIRAIYA — Basic Knowledge: chapters and lessons.
   Each lesson: [id, title, one-liner, explanation, "point|point|point", preview kind, preview config] */
window.XR_LEARN = [
{ id: 'web', t: 'How the web works', jp: '網', ic: 'globe', c: '#c4321d', l: [
 ['internet', 'How the internet works', 'Computers talking through cables, radio and routers.', 'The internet is a huge network of networks. Your phone sends small packets of data to a router, which passes them hop by hop across the world until they reach the right server, and the answer comes back the same way.', 'Data travels in small packets|Routers pick the next hop|Every device has an IP address', 'flow', { n: ['Your phone', 'Wi-Fi router', 'Internet provider', 'Server'], m: [[0, 1, 'packet'], [1, 2, 'packet'], [2, 3, 'GET /'], [3, 2, 'HTML'], [2, 1, 'HTML'], [1, 0, 'page!']] }],
 ['website', 'What a website is', 'Files a server sends to your browser.', 'A website is a set of files: HTML for structure, CSS for looks and JavaScript for behaviour. A server stores them and sends them to any browser that asks. The browser turns them into the page you see.', 'HTML = structure|CSS = style|JS = behaviour', 'layers', { l: [['HTML', 'The bones: headings, text, images, links'], ['CSS', 'The skin: colours, fonts, layout, motion'], ['JavaScript', 'The brain: clicks, data, logic'], ['Browser', 'Puts it all together on screen']] }],
 ['domain', 'Domain names', 'A human name for a server address.', 'A domain like xiraiya.dev is a name you rent from a registrar, usually for a year at a time. It is easier to remember than an IP address like 185.199.108.153, and you can point it at any server you like.', 'Rented yearly from a registrar|Points to an IP address|Subdomains are free: shop.example.com', 'url', {}],
 ['dns', 'DNS', 'The phone book of the internet.', 'When you type a domain, your device asks a DNS resolver for its IP address. The resolver asks the root servers, then the .com servers, then the domain’s own name server, and caches the answer so the next visit is instant.', 'Turns names into IP addresses|Answers are cached (TTL)|A, CNAME, MX and TXT records', 'flow', { n: ['Browser', 'Resolver', 'Root .', '.dev server', 'Name server'], m: [[0, 1, 'xiraiya.dev?'], [1, 2, 'who knows .dev?'], [2, 1, 'ask .dev'], [1, 3, 'xiraiya.dev?'], [3, 1, 'ask ns1'], [1, 4, 'xiraiya.dev?'], [4, 1, '185.199.108.153'], [1, 0, '185.199.108.153']] }],
 ['hosting', 'Hosting', 'A computer that is always on and online.', 'Hosting is renting space on a server so your site is reachable 24/7. Static sites can live on free hosts like GitHub Pages. Apps with a backend need a VPS or a platform like Vercel, Render or a cloud provider.', 'Static hosting: files only, often free|VPS: your own virtual server|Managed platforms deploy from Git', 'compare', { a: ['Static host', 'HTML, CSS, JS files · fast · cheap or free · no database'], b: ['App server', 'Runs code · database · logins · payments · costs more'] }],
 ['http', 'HTTP and HTTPS', 'The language browsers and servers speak.', 'HTTP is a simple request and response: the browser asks for something with a method like GET, and the server replies with a status code and content. HTTPS is the same conversation, encrypted so nobody in between can read or change it.', 'Request: method + URL + headers|Response: status + headers + body|HTTPS encrypts everything', 'code', { lang: 'http', c: 'GET /products HTTP/1.1\nHost: shop.example.com\nAccept: application/json', o: 'HTTP/1.1 200 OK\nContent-Type: application/json\n\n[{"id":1,"name":"Keyboard","price":129}]' }],
 ['url', 'Anatomy of a URL', 'Every part of an address has a job.', 'A URL tells the browser which protocol to use, which server to ask, which page to load and extra details like search terms. Knowing the parts helps you read links, spot fake ones and build clean routes.', 'Protocol, domain, path|Query ?key=value|Fragment #section stays in the browser', 'url', {}],
 ['render', 'How a browser draws a page', 'From HTML text to pixels in about 100 ms.', 'The browser reads HTML into the DOM, CSS into the CSSOM, combines them into a render tree, works out where everything goes (layout), then paints pixels and composites layers. Changing layout is expensive; changing transform or opacity is cheap.', 'Parse → style → layout → paint → composite|Animate transform and opacity|Avoid layout thrashing', 'steps', { s: [['Parse HTML', 'Build the DOM tree'], ['Parse CSS', 'Build the CSSOM'], ['Style', 'Match rules to elements'], ['Layout', 'Work out sizes and positions'], ['Paint', 'Fill in pixels'], ['Composite', 'Stack layers on the GPU']] }],
 ['clientserver', 'Client and server', 'Who does what.', 'The client is the browser or app on the user’s device. The server is the computer that stores data and runs the logic you cannot trust to the client, like prices, payments and passwords.', 'Never trust the client|Server checks everything|Client makes it feel fast', 'flow', { n: ['Client (browser)', 'Server', 'Database'], m: [[0, 1, 'POST /order'], [1, 2, 'check stock'], [2, 1, '3 left'], [1, 0, 'order #4822 ✓']] }],
 ['cookies', 'Cookies and sessions', 'How a site remembers you.', 'HTTP forgets you after every request. A cookie is a small value the server asks the browser to send back each time, usually a session ID. The server looks it up to know who you are and what is in your cart.', 'Session ID in a cookie|HttpOnly: JavaScript cannot read it|Secure + SameSite for safety', 'flow', { n: ['Browser', 'Server', 'Session store'], m: [[0, 1, 'login'], [1, 2, 'save session 8f3a'], [1, 0, 'Set-Cookie: sid=8f3a'], [0, 1, 'Cookie: sid=8f3a'], [1, 2, 'who is 8f3a?'], [2, 1, 'Nusrat'], [1, 0, 'Hi Nusrat']] }],
 ['cdn', 'CDN', 'Copies of your site close to every visitor.', 'A content delivery network keeps copies of your images, scripts and pages on servers in many cities. A visitor in Dhaka gets files from a nearby server instead of one in the USA, so the site loads much faster and survives traffic spikes.', 'Edge servers in many cities|Cache static files|Protects against traffic floods', 'flow', { n: ['Visitor in Dhaka', 'CDN edge (Dhaka)', 'Origin (USA)'], m: [[0, 1, 'logo.png?'], [1, 2, 'first time: fetch'], [2, 1, 'logo.png'], [1, 0, 'logo.png · 180 ms'], [0, 1, 'logo.png?'], [1, 0, 'cached · 12 ms']] }],
 ['status', 'HTTP status codes', 'Three digits that say what happened.', 'Every response starts with a status code. 2xx means success, 3xx means go somewhere else, 4xx means the request was wrong, and 5xx means the server broke. They help browsers, apps and search engines react correctly.', '200 OK, 201 Created|301 moved, 304 not modified|404 not found, 500 server error', 'status', {}]
]},
{ id: 'css', t: 'HTML & CSS', jp: '型', ic: 'code', c: '#2c6f65', l: [
 ['html', 'HTML structure', 'Tags that describe content.', 'HTML wraps content in tags like <h1>, <p> and <img>. The browser reads them to understand what each piece is. Good structure makes pages readable by people, search engines and screen readers.', 'Tags open and close|Attributes add details|Nesting builds a tree', 'code', { lang: 'html', c: '<article class="card">\n  <h2>Keyboard</h2>\n  <p>Low profile, hot-swap.</p>\n  <button>Add to cart</button>\n</article>', o: '__html__' }],
 ['semantic', 'Semantic HTML', 'Use the tag that says what it is.', 'Use <header>, <nav>, <main>, <article>, <button> and friends instead of a pile of <div>s. Screen readers, search engines and keyboard users get the meaning for free, and your CSS gets simpler.', '<button> not <div onclick>|One <h1> per page|Landmarks: header, nav, main, footer', 'compare', { a: ['Div soup', '<div class="btn" onclick=…> · no keyboard · no meaning'], b: ['Semantic', '<button> · focusable · announced as a button · works with Enter'] }],
 ['dom', 'The DOM', 'The page as a live tree of objects.', 'The browser turns HTML into the Document Object Model: a tree where every tag is a node. JavaScript can find nodes, change text, add classes or create new elements, and the page updates immediately.', 'Tree of nodes|JS reads and changes it|Changes show up instantly', 'dom', {}],
 ['selectors', 'CSS selectors', 'How CSS finds what to style.', 'A selector picks elements: by tag (p), class (.card), id (#top), attribute ([type=email]) or state (:hover). Combine them to target exactly what you need without adding extra classes everywhere.', '.class and #id|:hover, :focus, :nth-child|Specificity decides who wins', 'selector', {}],
 ['boxmodel', 'The box model', 'Every element is a box with layers.', 'Each element has content, then padding, then a border, then margin. Padding is space inside the border, margin is space outside it. box-sizing: border-box makes widths include padding and border, which is what you usually want.', 'Content → padding → border → margin|box-sizing: border-box|Margins can collapse', 'css', { demo: 'box' }],
 ['flexbox', 'Flexbox', 'Line things up in one direction.', 'Flexbox lays out children in a row or a column, then lets you control spacing, alignment and wrapping. It is perfect for nav bars, button groups, cards in a row and centering anything.', 'display: flex|justify-content = main axis|align-items = cross axis', 'css', { demo: 'flex' }],
 ['grid', 'CSS Grid', 'Two-dimensional layouts.', 'Grid places items into rows and columns at the same time. Define the tracks once, and items flow into them. repeat(auto-fill, minmax(200px, 1fr)) builds a responsive card grid with a single line.', 'grid-template-columns|gap for spacing|Items can span tracks', 'css', { demo: 'grid' }],
 ['responsive', 'Responsive design', 'One site, every screen size.', 'Responsive design uses fluid widths, flexible images and media queries so the same page works on a phone, a tablet and a wide monitor. Start with the phone layout, then add rules as the screen grows.', 'Mobile first|@media (min-width: …)|clamp() for fluid sizes', 'resp', {}],
 ['color', 'Colour and gradients', 'Palettes, contrast and blends.', 'Pick a small palette: a background, a text colour, one accent and a few greys. Gradients blend colours for depth. Always check that text has enough contrast against what is behind it.', 'hex, rgb, hsl|linear- and radial-gradient|Contrast 4.5:1 for text', 'css', { demo: 'color' }],
 ['type', 'Typography', 'Fonts do half the design work.', 'Choose one font for headings and one for body text. Set a clear scale of sizes, comfortable line height (about 1.5 for body) and a line length around 60 to 75 characters.', 'Two fonts at most|Line height ~1.5|Scale sizes consistently', 'css', { demo: 'type' }],
 ['shadow', 'Shadows and depth', 'Make things float, subtly.', 'box-shadow adds depth: an offset, a blur, a spread and a colour. Layer two soft shadows for realism. Bigger blur and offset feel higher off the page.', 'x y blur spread colour|Layer shadows|Keep them soft', 'css', { demo: 'shadow' }],
 ['transform', 'Transforms', 'Move, rotate and scale without breaking layout.', 'transform changes how an element is drawn, not where it sits in the layout. That makes it cheap to animate, which is why almost all smooth motion on the web uses translate, scale and rotate.', 'translate, rotate, scale|No layout recalculation|3D with perspective', 'css', { demo: 'transform' }],
 ['cssvars', 'CSS variables', 'Change one value, update everything.', 'Custom properties like --accent: #c4321d store values you reuse. Change the variable once, for example in dark mode, and every rule that uses it updates.', '--name: value|var(--name)|Perfect for themes', 'css', { demo: 'vars' }]
]},
{ id: 'js', t: 'JavaScript', jp: '脳', ic: 'terminal', c: '#b7862a', l: [
 ['variables', 'Variables', 'Named boxes for values.', 'Use const for values that never get reassigned and let for ones that do. Values can be numbers, text (strings), true or false (booleans), lists (arrays) or objects.', 'const by default|let when it changes|Avoid var', 'code', { lang: 'js', c: 'const name = "Xiraiya";\nlet cart = 0;\ncart = cart + 2;\nconsole.log(name, "has", cart, "items");', o: 'Xiraiya has 2 items' }],
 ['functions', 'Functions', 'Reusable blocks of code.', 'A function takes inputs, does something and can return a result. Give it a clear name and keep it doing one job. Arrow functions are a short way to write small ones.', 'Inputs → work → output|One job each|Arrow: (a, b) => a + b', 'code', { lang: 'js', c: 'const total = (price, qty) => price * qty;\nconst withTax = n => Math.round(n * 1.05);\nconsole.log(withTax(total(129, 2)));', o: '271' }],
 ['events', 'Events', 'Reacting to clicks, typing and scrolling.', 'The browser fires events when things happen. addEventListener runs your function when a button is clicked, a key is pressed or a form is submitted.', 'addEventListener(type, fn)|click, input, submit, keydown|event.preventDefault()', 'events', {}],
 ['arrays', 'Arrays, map and filter', 'Working with lists.', 'Arrays hold ordered lists. map transforms every item, filter keeps the ones that pass a test, and reduce combines them into one value. Together they replace most loops.', 'map → transform|filter → keep some|reduce → combine', 'code', { lang: 'js', c: 'const prices = [129, 45, 260, 89];\nconst cheap = prices.filter(p => p < 100);\nconst sum = prices.reduce((a, p) => a + p, 0);\nconsole.log(cheap, sum);', o: '[45, 89] 523' }],
 ['objects', 'Objects and JSON', 'Structured data.', 'An object groups related values under names. JSON is the same idea written as text, so it can travel between a server and a browser. JSON.stringify turns an object into text; JSON.parse turns it back.', '{ key: value }|JSON is text|stringify and parse', 'json', { o: { id: 4822, customer: { name: 'Nusrat', city: 'Dhaka' }, items: [{ sku: 'KB-75', qty: 1, price: 129 }], paid: true } }],
 ['async', 'Async and promises', 'Doing things that take time.', 'Network calls and timers take time. A Promise is a value that arrives later. async and await let you write that code top to bottom, without freezing the page while you wait.', 'await pauses the function, not the page|Promise.all runs in parallel|Always handle errors', 'async', {}],
 ['fetch', 'Fetch', 'Talking to APIs from the browser.', 'fetch sends an HTTP request and returns a promise for the response. Read it with .json(), check response.ok, and show a loading state while you wait.', 'fetch(url, options)|await res.json()|Check res.ok', 'code', { lang: 'js', c: 'const res = await fetch("/api/products?limit=2");\nif (!res.ok) throw new Error(res.status);\nconst data = await res.json();\nconsole.log(data.map(p => p.name));', o: '["Keyboard", "Mouse"]' }],
 ['storage', 'localStorage', 'Remember things in the browser.', 'localStorage saves small strings per site that survive page reloads. Great for settings, drafts and carts. Never store passwords or tokens there, because any script on the page can read it.', 'setItem and getItem|Strings only (use JSON)|Not for secrets', 'storage', {}],
 ['dommanip', 'Changing the page', 'querySelector, classList, textContent.', 'Find an element with querySelector, then change its text, classes, styles or attributes. Toggle a class and let CSS handle the look; it keeps your JavaScript short.', 'document.querySelector|el.classList.toggle|el.textContent = …', 'events', { toggle: 1 }],
 ['modules', 'Modules', 'Split code into files.', 'ES modules let one file export functions and another import them. Each file has its own scope, so names do not clash, and bundlers can drop code you never use.', 'export and import|One job per file|Tree shaking removes unused code', 'code', { lang: 'js', c: '// cart.js\nexport const add = (cart, item) => [...cart, item];\n\n// app.js\nimport { add } from "./cart.js";\nconsole.log(add([], "keyboard"));', o: '["keyboard"]' }],
 ['errors', 'Errors and try/catch', 'Fail gracefully.', 'Things go wrong: the network drops, data is missing. Wrap risky code in try/catch, show the user a helpful message and log the details for yourself.', 'try { } catch (e) { }|Show a friendly message|Log the real error', 'code', { lang: 'js', c: 'try {\n  const user = JSON.parse("{bad json");\n} catch (e) {\n  console.log("Could not read the data. Please retry.");\n}', o: 'Could not read the data. Please retry.' }],
 ['typescript', 'TypeScript', 'JavaScript with types.', 'TypeScript adds types to JavaScript, so your editor catches mistakes like passing text where a number is expected before the code runs. It compiles down to plain JavaScript.', 'Catch bugs early|Better autocomplete|Compiles to JS', 'code', { lang: 'ts', c: 'type Product = { name: string; price: number };\nconst p: Product = { name: "Mouse", price: "29" };', o: 'Error: Type "string" is not assignable to type "number".' }]
]},
{ id: 'ui', t: 'UI design', jp: '顔', ic: 'palette', c: '#5f4f95', l: [
 ['whatui', 'What UI is', 'Everything you see and touch.', 'The user interface is the visible layer: layout, colour, type, buttons, forms and icons. Good UI is clear first and beautiful second. People should know what to do without thinking.', 'Clear before clever|Consistent parts|Designed for the smallest screen first', 'ui', { demo: 'card' }],
 ['buttons', 'Buttons and states', 'Every button has five moods.', 'A button needs a default, hover, pressed, focus and disabled state, plus often loading. Each one tells the user something: you can click me, you are clicking me, I am busy, you cannot use me yet.', 'Default, hover, pressed|Focus ring for keyboards|Loading and disabled', 'ui', { demo: 'btn' }],
 ['forms', 'Forms and validation', 'Help people get it right.', 'Label every field, show examples, validate as people type, and put the error message next to the field in plain words. Keep forms short; every extra field loses users.', 'Labels above fields|Inline errors|Only ask what you need', 'ui', { demo: 'form' }],
 ['cards', 'Cards', 'A box that holds one idea.', 'Cards group an image, a title, a little text and an action. They work in grids, stack nicely on phones and make scanning easy.', 'One idea per card|Clear action|Consistent size', 'ui', { demo: 'card' }],
 ['nav', 'Navigation', 'Where am I, where can I go?', 'Navigation should show where you are, where you can go and how to get back. Keep the main menu short, highlight the current page, and on phones use a bottom bar or a clear menu button.', 'Highlight the current page|5 to 7 main items|Thumb-friendly on phones', 'ui', { demo: 'nav' }],
 ['modals', 'Modals', 'Interrupt only when it matters.', 'A modal takes over the screen for one focused task, like confirming a delete. Trap focus inside, close on Escape, and never open one the moment a page loads.', 'One task only|Esc and backdrop close it|Return focus when closed', 'ui', { demo: 'modal' }],
 ['toasts', 'Toasts', 'Quick, quiet confirmations.', 'A toast is a small message that appears for a few seconds: Saved, Copied, Added to cart. It confirms an action without blocking anything.', 'Short text|Auto-dismiss|Undo when possible', 'ui', { demo: 'toast' }],
 ['tabs', 'Tabs', 'Switch views in place.', 'Tabs show one panel at a time from a small set. The active tab must look clearly different, and an animated indicator helps the eye follow the change.', 'Two to six tabs|Clear active state|Keyboard arrows move between tabs', 'ui', { demo: 'tabs' }],
 ['skeleton', 'Loading skeletons', 'Show the shape before the data.', 'Skeleton screens draw grey placeholders in the shape of the content that is coming. The page feels faster than a spinner because people can see what will appear.', 'Match the real layout|Subtle shimmer|Swap in content smoothly', 'ui', { demo: 'skel' }],
 ['darkmode', 'Dark mode', 'Same design, lights off.', 'Dark mode is not just inverted colours. Use dark greys instead of pure black, lighten the accent a little, and lower shadows. CSS variables make switching instant.', 'Dark grey, not #000|Adjust accent colours|Respect the system setting', 'ui', { demo: 'dark' }],
 ['tokens', 'Design tokens', 'The shared values behind a design.', 'Tokens are named values for colour, spacing, radius, font size and motion. Designers and developers use the same names, so the design and the code never drift apart.', 'Name values once|Use them everywhere|Theme by swapping tokens', 'css', { demo: 'vars' }],
 ['spacing', 'Spacing and grids', 'The invisible structure.', 'Use a spacing scale like 4, 8, 12, 16, 24, 32, 48. Related things sit closer together, unrelated things further apart. Consistent spacing is what makes a design look professional.', 'Use a scale|Close = related|Align to a grid', 'ui', { demo: 'spacing' }],
 ['toggles', 'Switches and checkboxes', 'On, off, and many.', 'A switch changes a setting immediately. A checkbox is for choices you confirm later, or picking several things. Label them clearly with what happens when they are on.', 'Switch = instant|Checkbox = choose, then submit|Clear labels', 'ui', { demo: 'toggle' }]
]},
{ id: 'ux', t: 'UX', jp: '心', ic: 'users', c: '#a4473a', l: [
 ['whatux', 'What UX is', 'How it feels to use it.', 'User experience covers the whole journey: finding the product, understanding it, using it and coming back. Good UX removes friction, confusion and waiting.', 'Design for real tasks|Remove friction|Test with real people', 'ux', { demo: 'flow' }],
 ['hierarchy', 'Visual hierarchy', 'Show what matters first.', 'Size, weight, colour and position tell people what to read first. One clear headline, one main action and everything else quieter.', 'One main action|Big = important|Group related items', 'ux', { demo: 'hier' }],
 ['fitts', 'Fitts’s law', 'Big, close targets are faster.', 'The time to hit a target depends on its size and distance. Make important buttons large and put them where the thumb or cursor already is.', 'Bigger targets|Closer targets|44 px minimum on touch', 'ux', { demo: 'fitts' }],
 ['hick', 'Hick’s law', 'More choices, slower decisions.', 'Every extra option makes people take longer to choose. Show a few good choices, hide the rest behind More, and recommend one.', 'Fewer options|Highlight a default|Progressive disclosure', 'ux', { demo: 'hick' }],
 ['contrast', 'Contrast and accessibility', 'Everyone should be able to read it.', 'Text needs a contrast ratio of at least 4.5:1 against its background. Do not use colour alone to mean something, support the keyboard and add alt text to images.', '4.5:1 for body text|Not colour alone|Keyboard and screen readers', 'ux', { demo: 'contrast' }],
 ['feedback', 'Feedback', 'Every action gets a reaction.', 'When someone clicks, the interface should respond within 100 ms: a pressed state, a spinner, a success message. Silence makes people click again or give up.', 'Respond under 100 ms|Show progress|Confirm success', 'ux', { demo: 'feedback' }],
 ['errormsg', 'Error messages', 'Say what went wrong and how to fix it.', 'A good error message is human, specific and helpful: what happened, why, and what to do next. Never blame the user and never show a raw code.', 'Plain words|Specific|Offer the fix', 'compare', { a: ['Bad', 'Error 422: Unprocessable entity'], b: ['Good', 'That phone number looks one digit short. Try 01712 345 678.'] }],
 ['consistency', 'Consistency', 'Same thing, same look, same place.', 'When buttons, words and layouts behave the same everywhere, people learn once and move fast. Break consistency only on purpose.', 'Reuse components|Same words for same actions|Predictable placement', 'ux', { demo: 'consist' }],
 ['whitespace', 'Whitespace', 'Empty space is not wasted space.', 'Room around elements makes content easier to scan and feel calmer and more premium. Crowded layouts feel cheap and are harder to read.', 'Breathing room|Group with space|Less is more', 'ux', { demo: 'white' }],
 ['mobilefirst', 'Mobile first', 'Design for the thumb.', 'Most visits come from phones. Design the small screen first: one column, big tap targets, the main action within thumb reach, and nothing that needs hover.', 'One column|Thumb zone|No hover-only features', 'resp', {}],
 ['empty', 'Empty states', 'Nothing here yet? Help them start.', 'An empty cart, inbox or search result is a chance to guide people. Explain what goes here and offer the next step, like a button to browse or create.', 'Explain the space|Offer an action|Add personality', 'ux', { demo: 'empty' }],
 ['userflow', 'User flows', 'The path from want to done.', 'A user flow maps each step someone takes to reach a goal, like buying a product. Count the steps and remove every one you can.', 'Map every step|Remove steps|Test the flow', 'steps', { s: [['Lands on page', 'From an ad or search'], ['Finds product', 'Search or browse'], ['Adds to cart', 'One tap'], ['Checks out', 'Guest checkout, no signup'], ['Pays', 'bKash, card or COD'], ['Done', 'Confirmation + SMS']] }]
]},
{ id: 'motion', t: 'Motion UI', jp: '動', ic: 'film', c: '#d9a441', l: [
 ['easing', 'Easing curves', 'Nothing in real life moves linearly.', 'Easing changes speed over time. ease-out starts fast and settles, which feels responsive for things entering. ease-in speeds up, good for things leaving. Linear feels robotic.', 'ease-out for entering|ease-in for leaving|cubic-bezier for custom curves', 'motion', { demo: 'ease' }],
 ['duration', 'Duration', 'Fast enough to feel instant, slow enough to see.', 'Small UI changes should take 150 to 300 ms. Larger movements across the screen can take 400 to 600 ms. Anything longer starts to feel slow.', '150–300 ms for UI|Bigger distance, longer time|Never make people wait', 'motion', { demo: 'dur' }],
 ['keyframes', 'Keyframes', 'Multi-step animations.', '@keyframes describes an animation step by step: at 0% do this, at 50% that, at 100% this. Attach it with the animation property and control duration, delay and repeats.', '@keyframes name { }|animation: name 1s infinite|Use percentages', 'motion', { demo: 'key' }],
 ['micro', 'Micro-interactions', 'Tiny moments that feel alive.', 'A heart that pops when liked, a button that presses in, a checkbox that draws its tick. Small, quick animations confirm actions and make an interface feel crafted.', 'Confirm an action|Under 300 ms|Delight, do not distract', 'motion', { demo: 'micro' }],
 ['stagger', 'Stagger', 'One after another, not all at once.', 'Delaying each item by 40 to 80 ms makes a list feel like it flows in. The eye follows the sequence instead of being hit by everything at once.', 'Small delay per item|40–80 ms|Cap the total time', 'motion', { demo: 'stagger' }],
 ['spring', 'Spring physics', 'Motion with bounce and weight.', 'Springs are defined by stiffness and damping instead of duration. They overshoot a little and settle, which feels physical and playful.', 'Stiffness + damping|Slight overshoot|Feels natural', 'motion', { demo: 'spring' }],
 ['reveal', 'Scroll reveal', 'Content that arrives as you scroll.', 'IntersectionObserver tells you when an element enters the screen. Add a class and let CSS fade and slide it in. Keep it subtle and only do it once.', 'IntersectionObserver|Fade + small slide|Once, not every time', 'motion', { demo: 'reveal' }],
 ['parallax', 'Parallax', 'Layers moving at different speeds.', 'Background layers move slower than the foreground, which creates depth. Use it sparingly and respect people who turn motion off.', 'Different speeds = depth|Subtle movement|Turn off for reduced motion', 'motion', { demo: 'parallax' }],
 ['pagetrans', 'Page transitions', 'Smooth hand-offs between screens.', 'Instead of a hard cut, a quick fade, slide or shared element carries the eye from one screen to the next. The View Transitions API makes this easy in modern browsers.', 'Keep context|Under 400 ms|Shared elements', 'motion', { demo: 'page' }],
 ['loaders', 'Loaders', 'Waiting, made bearable.', 'Spinners for short waits, progress bars when you know how long, skeletons for content. Show them only if the wait is longer than about 300 ms.', 'Spinner, bar, skeleton|Show progress when known|Avoid flashing', 'motion', { demo: 'loader' }],
 ['reducedmotion', 'Reduced motion', 'Some people need less movement.', 'Motion can make some people dizzy. The prefers-reduced-motion media query tells you when to swap big movement for simple fades or none at all.', '@media (prefers-reduced-motion)|Keep fades, drop big movement|Never required to use the site', 'code', { lang: 'css', c: '@media (prefers-reduced-motion: reduce) {\n  * { animation: none !important;\n      transition: none !important; }\n}', o: 'Motion off for people who ask for it.' }]
]},
{ id: 'api', t: 'Backend & APIs', jp: '裏', ic: 'server', c: '#2f6fe0', l: [
 ['backend', 'What a backend is', 'The kitchen behind the restaurant.', 'The backend is code running on a server: it checks logins, saves orders, talks to the database, sends emails and takes payments. Users never see it, but everything depends on it.', 'Runs on a server|Owns the data|Enforces the rules', 'layers', { l: [['Frontend', 'What users see and click'], ['API', 'The door between them'], ['Backend logic', 'Rules, prices, permissions'], ['Database', 'Where data lives']] }],
 ['whatapi', 'What an API is', 'A menu of things one program can ask another.', 'An API is a set of requests a program accepts and the answers it gives back. Your shop asks the payment API to charge a card; the weather app asks a weather API for the forecast.', 'Request → response|Documented endpoints|Usually JSON over HTTPS', 'flow', { n: ['Your app', 'API', 'Service'], m: [[0, 1, 'GET /weather?city=Dhaka'], [1, 2, 'look up'], [2, 1, '31°C, humid'], [1, 0, '{ "temp": 31 }']] }],
 ['rest', 'REST methods', 'GET, POST, PUT, PATCH, DELETE.', 'REST APIs use HTTP methods as verbs on resources. GET reads, POST creates, PUT or PATCH updates and DELETE removes. URLs name the thing: /users/42/orders.', 'GET reads, POST creates|PATCH updates, DELETE removes|Nouns in URLs', 'rest', {}],
 ['jsonapi', 'JSON responses', 'The common language of APIs.', 'Most APIs answer in JSON: nested objects and lists of values. A good response is predictable, uses clear names and includes error details when something fails.', 'Consistent shape|Clear names|Errors with a message', 'json', { o: { ok: true, data: { id: 42, name: 'Nusrat', orders: 3 }, meta: { took_ms: 18 } } }],
 ['jwt', 'Tokens and JWT', 'Proof of who you are, in every request.', 'After login, the server gives the client a token. The client sends it with each request in the Authorization header. A JWT carries signed data the server can verify without a database lookup.', 'Authorization: Bearer …|Signed, not encrypted|Short expiry + refresh', 'jwt', {}],
 ['oauth', 'OAuth login', 'Sign in with Google, safely.', 'OAuth lets a user log in through Google or GitHub without giving you their password. The provider asks the user, then sends your server a code it swaps for a token.', 'You never see the password|User approves access|Code → token exchange', 'flow', { n: ['User', 'Your site', 'Google'], m: [[0, 1, 'Sign in with Google'], [1, 2, 'redirect'], [0, 2, 'approve'], [2, 1, 'code=abc'], [1, 2, 'swap code'], [2, 1, 'token + profile'], [1, 0, 'Welcome!']] }],
 ['webhooks', 'Webhooks', 'The API calls you.', 'Instead of asking every minute whether a payment arrived, you give the service a URL. When the event happens, it sends a POST to that URL. Verify the signature before trusting it.', 'Event-driven|Your URL gets a POST|Verify the signature', 'flow', { n: ['Customer', 'Payment gateway', 'Your server', 'Telegram'], m: [[0, 1, 'pays ৳2,400'], [1, 2, 'POST /webhook (signed)'], [2, 2, 'verify HMAC'], [2, 3, 'New order #4822'], [2, 1, '200 OK']] }],
 ['websockets', 'WebSockets', 'A line that stays open.', 'HTTP asks and answers once. A WebSocket keeps a connection open so the server can push updates instantly: chat messages, live prices, game moves.', 'Two-way and real time|Stays connected|Chat, trading, games', 'ws', {}],
 ['ratelimit', 'Rate limiting', 'Stop one client from flooding you.', 'A rate limit allows, say, 60 requests per minute per user or IP. Past that, the server answers 429 Too Many Requests. It protects against abuse, bugs and brute force.', 'Limit per user or IP|429 Too Many Requests|Protects the server', 'atk', { demo: 'rate' }],
 ['node', 'Servers and Node.js', 'JavaScript on the server.', 'Node.js runs JavaScript outside the browser. With a framework like Express you define routes: when a GET arrives at /products, run this function and send back JSON.', 'Same language front and back|Routes → handlers|Huge package ecosystem', 'code', { lang: 'js', c: 'import express from "express";\nconst app = express();\napp.get("/products", (req, res) => {\n  res.json([{ name: "Keyboard", price: 129 }]);\n});\napp.listen(3000);', o: 'Server running on http://localhost:3000' }],
 ['env', 'Environment variables', 'Secrets live outside the code.', 'API keys, database passwords and tokens go in environment variables, not in your code. A .env file keeps them local, and it must never be committed to Git.', '.env file, never in Git|process.env.KEY|Different values per environment', 'code', { lang: 'bash', c: '# .env  (listed in .gitignore)\nDATABASE_URL=mysql://app:••••@db:3306/shop\nBKASH_SECRET=••••••••', o: 'Loaded 2 secrets. Nothing leaked to GitHub.' }],
 ['cache', 'Caching and Redis', 'Remember answers so you do not repeat work.', 'A cache stores results you will need again, like the product list, in fast memory. Redis is the popular choice. Set an expiry so stale data eventually refreshes.', 'Memory is fast, disk is slow|Set a TTL|Invalidate on change', 'flow', { n: ['App', 'Redis cache', 'Database'], m: [[0, 1, 'products?'], [1, 0, 'miss'], [0, 2, 'SELECT … (40 ms)'], [2, 0, 'rows'], [0, 1, 'save 60 s'], [0, 1, 'products?'], [1, 0, 'hit (0.4 ms)']] }]
]},
{ id: 'db', t: 'Databases', jp: '蔵', ic: 'database', c: '#1f8a5b', l: [
 ['whatdb', 'What a database is', 'Organised, permanent storage.', 'A database stores data so it survives restarts, can be searched quickly and can be used by many people at once. Shops keep products, customers and orders in one.', 'Permanent|Searchable|Safe with many users', 'sql', { q: ['all'] }],
 ['tables', 'Tables, rows and columns', 'Like a spreadsheet with rules.', 'A table holds one kind of thing. Each row is one record, each column one property, and every column has a type such as number, text or date.', 'Table = one kind of thing|Row = one record|Column = one property with a type', 'sql', { q: ['all'] }],
 ['mysql', 'What MySQL is', 'The world’s most popular open-source database.', 'MySQL is a relational database: data lives in tables that link to each other, and you talk to it with SQL. It powers WordPress and countless shops. PostgreSQL and MariaDB are close cousins.', 'Relational (tables + links)|Speaks SQL|Free and everywhere', 'sql', { q: ['all', 'where', 'join'] }],
 ['select', 'SELECT', 'Read data.', 'SELECT picks columns from a table. Add WHERE to filter, ORDER BY to sort and LIMIT to take only a few. It is the query you will write most.', 'SELECT columns FROM table|* means all columns|Pick only what you need', 'sql', { q: ['all', 'cols'] }],
 ['where', 'WHERE', 'Filter rows.', 'WHERE keeps only rows that match a condition. Combine conditions with AND and OR, match text with LIKE, and check ranges with BETWEEN.', '= <> < > comparisons|AND, OR|LIKE "%text%"', 'sql', { q: ['where', 'like'] }],
 ['orderlimit', 'ORDER BY and LIMIT', 'Sort and page results.', 'ORDER BY sorts by one or more columns, ascending or descending. LIMIT with OFFSET gives you pages of results, like page 2 of products.', 'ORDER BY col DESC|LIMIT 10 OFFSET 20|Pagination', 'sql', { q: ['order'] }],
 ['crud', 'INSERT, UPDATE, DELETE', 'Change data.', 'INSERT adds rows, UPDATE changes them and DELETE removes them. Always include WHERE on UPDATE and DELETE, or you change every row in the table.', 'INSERT INTO … VALUES|UPDATE … SET … WHERE|DELETE … WHERE (never forget it)', 'sql', { q: ['insert', 'update', 'delete'] }],
 ['join', 'JOIN', 'Combine tables.', 'A JOIN links rows from two tables using a shared key, like orders.user_id = users.id. That way you store each customer once and connect them to many orders.', 'Link with keys|INNER JOIN = matches only|LEFT JOIN keeps all from the left', 'sql', { q: ['join'] }],
 ['groupby', 'GROUP BY and COUNT', 'Summaries and reports.', 'GROUP BY collects rows that share a value and lets you COUNT, SUM or AVG them. It answers questions like how many orders each city made.', 'COUNT, SUM, AVG|GROUP BY column|HAVING filters groups', 'sql', { q: ['group'] }],
 ['keys', 'Primary and foreign keys', 'How rows find each other.', 'A primary key uniquely identifies each row, usually an id. A foreign key in another table points to it. The database can then refuse orders for customers that do not exist.', 'Primary key = unique id|Foreign key = link|Keeps data consistent', 'sql', { q: ['join'] }],
 ['indexes', 'Indexes', 'The book index for your data.', 'Without an index, the database reads every row to find a match. An index on a column lets it jump straight there, turning seconds into milliseconds. Too many indexes slow down writes.', 'Speeds up WHERE and JOIN|Costs a little on writes|Index what you search by', 'index', {}],
 ['nosql', 'SQL vs NoSQL', 'Tables or documents.', 'SQL databases use strict tables and relations, great for orders and money. NoSQL databases like MongoDB store flexible JSON documents, handy for data whose shape changes a lot.', 'SQL: structured, relations|NoSQL: flexible documents|Pick by the data, not the hype', 'compare', { a: ['MySQL (SQL)', 'users table + orders table · JOIN · strict types · transactions'], b: ['MongoDB (NoSQL)', '{ user, orders: [ … ] } in one document · flexible · easy to scale'] }],
 ['transactions', 'Transactions', 'All or nothing.', 'A transaction groups several changes so they all succeed or none do. Moving money takes it from one account and adds it to another; a crash halfway must not lose it.', 'BEGIN … COMMIT|ROLLBACK on error|ACID guarantees', 'txn', {}],
 ['backups', 'Backups', 'Your undo button for disasters.', 'Back up the database automatically every day, keep copies in another place, and actually test restoring them. A backup you have never restored is only a hope.', 'Automatic and daily|Stored off-site|Test the restore', 'steps', { s: [['Nightly dump', 'mysqldump at 03:00'], ['Encrypt', 'AES-256'], ['Upload off-site', 'Another provider or region'], ['Keep 30 days', 'Delete older copies'], ['Test monthly', 'Restore into a spare database']] }]
]},
{ id: 'sec', t: 'Security', jp: '守', ic: 'shield', c: '#9c2a1b', l: [
 ['howsec', 'How website security works', 'Layers, not one lock.', 'Security is defence in depth: HTTPS on the wire, validated input, hashed passwords, least privilege, updated software, backups and monitoring. If one layer fails, the next one stops the attacker.', 'Many layers|Assume one will fail|Monitor and update', 'layers', { l: [['HTTPS', 'Encrypts traffic'], ['Firewall + rate limits', 'Blocks floods and scanners'], ['Validation', 'Rejects bad input'], ['Auth + permissions', 'Only the right people'], ['Hashed data + backups', 'Damage stays small']] }],
 ['https', 'HTTPS and TLS', 'The padlock in the address bar.', 'TLS encrypts traffic between browser and server and proves the server is who it claims to be, using a certificate. Free certificates from Let’s Encrypt mean every site should use HTTPS.', 'Encrypts traffic|Certificate proves identity|Free with Let’s Encrypt', 'flow', { n: ['Browser', 'Server'], m: [[0, 1, 'hello + ciphers'], [1, 0, 'certificate + key share'], [0, 0, 'verify certificate'], [0, 1, 'key share'], [1, 0, 'finished (encrypted)'], [0, 1, 'GET / 🔒']] }],
 ['hashing', 'Password hashing', 'Never store the real password.', 'Store a slow, salted hash (bcrypt or Argon2) instead of the password. At login, hash what the user typed and compare. If the database leaks, attackers still do not have the passwords.', 'One-way hash|Unique salt per user|bcrypt or Argon2, never MD5', 'hash', {}],
 ['sqli', 'SQL injection', 'When input becomes code.', 'If you paste user input straight into SQL, an attacker can type SQL of their own and read or delete your data. Prepared statements send the input separately, so it can never become a command.', 'Never concatenate input into SQL|Use prepared statements|Least-privilege DB user', 'atk', { demo: 'sqli' }],
 ['xss', 'Cross-site scripting (XSS)', 'When input becomes a script.', 'If you show user input as HTML, someone can post <script> and run it in every visitor’s browser, stealing sessions. Escape output, use textContent and add a Content Security Policy.', 'Escape on output|textContent, not innerHTML|Content-Security-Policy', 'atk', { demo: 'xss' }],
 ['csrf', 'CSRF', 'Tricking your browser into acting for you.', 'A malicious page can make your browser send a request to a site where you are logged in, like changing your email. SameSite cookies and CSRF tokens stop it.', 'SameSite=Lax or Strict|CSRF tokens on forms|Confirm sensitive actions', 'atk', { demo: 'csrf' }],
 ['brute', 'Brute force', 'Guessing passwords at machine speed.', 'Attackers try thousands of passwords per minute. Rate limits, lockouts after failed attempts, CAPTCHAs and two-factor authentication make that pointless.', 'Rate limit logins|Lock after failures|2FA', 'atk', { demo: 'brute' }],
 ['ddos', 'DDoS', 'Drowning a site in traffic.', 'A distributed denial of service sends floods of requests from thousands of machines. A CDN or firewall like Cloudflare absorbs and filters it before it reaches your server.', 'Floods from many machines|CDN + firewall absorb it|Cache everything you can', 'atk', { demo: 'ddos' }],
 ['phishing', 'Phishing', 'Fake pages that steal logins.', 'Phishing copies a real login page on a lookalike domain and sends people there by email or SMS. Check the address bar, use a password manager and turn on 2FA.', 'Check the domain|Password managers will not autofill fakes|2FA limits the damage', 'atk', { demo: 'phish' }],
 ['twofa', 'Two-factor authentication', 'Something you know + something you have.', '2FA asks for a second proof after the password, like a 6-digit code from an app. Even with a stolen password, an attacker without your phone is stuck.', 'Authenticator apps beat SMS|Backup codes|Passkeys are even better', 'totp', {}],
 ['leastpriv', 'Least privilege', 'Give each part only what it needs.', 'The website’s database user should not be able to drop tables. The support team does not need billing access. If one part is compromised, the damage stays small.', 'Minimum permissions|Separate accounts|Review access regularly', 'compare', { a: ['Risky', 'App connects as root · everyone is admin · shared passwords'], b: ['Safe', 'App user: SELECT/INSERT only · roles per job · personal logins'] }],
 ['headers', 'Security headers', 'Instructions that harden the browser.', 'Headers like Content-Security-Policy, Strict-Transport-Security and X-Frame-Options tell the browser to refuse inline scripts, always use HTTPS and never load your site inside someone else’s frame.', 'CSP blocks injected scripts|HSTS forces HTTPS|X-Frame-Options stops clickjacking', 'code', { lang: 'http', c: 'Content-Security-Policy: default-src \'self\'\nStrict-Transport-Security: max-age=31536000\nX-Frame-Options: DENY\nReferrer-Policy: strict-origin', o: 'Security grade: A+' }],
 ['updates', 'Updates and dependencies', 'Old software is the easiest way in.', 'Most hacks use known bugs in outdated plugins, themes and packages. Update regularly, remove what you do not use and let tools like Dependabot tell you about vulnerable versions.', 'Update weekly|Remove unused plugins|Automated alerts', 'term', { c: [['$ npm audit', '3 vulnerabilities (1 high)'], ['$ npm audit fix', 'fixed 3 of 3 vulnerabilities'], ['$ npm outdated', 'All packages up to date ✓']] }]
]},
{ id: 'hack', t: 'When you get hacked', jp: '急', ic: 'alert', c: '#e0442e', l: [
 ['signs', 'Signs you have been hacked', 'Know what to look for.', 'Strange admin users, spam pages in Google, redirects to other sites, unknown files, a sudden traffic spike or your host suspending the account are all warning signs. Act fast, but do not panic.', 'Unknown admins or files|Spam in search results|Redirects and warnings', 'steps', { s: [['Google shows spam pages', 'site:yourdomain.com'], ['Browser warning', 'Deceptive site ahead'], ['New admin user', 'You did not create it'], ['Host email', 'Account suspended for abuse']] }],
 ['first10', 'The first 10 minutes', 'Contain the damage.', 'Put the site in maintenance mode or take it offline, change the hosting and admin passwords from a clean device, and revoke API keys. Do not delete anything yet: you need the evidence.', 'Take it offline|Change passwords from a clean device|Keep the evidence', 'hack', { step: 0 }],
 ['investigate', 'Find how they got in', 'Logs tell the story.', 'Check server and access logs around the time things changed, look for recently modified files and new users, and review plugins with known vulnerabilities. Find the hole, or they will come back.', 'Access and error logs|Recently changed files|Outdated plugins', 'term', { c: [['$ find . -mtime -3 -name "*.php"', './uploads/cache.php  ← suspicious'], ['$ grep "POST /uploads" access.log', '185.x.x.x POST /uploads/cache.php 200'], ['$ wp user list --role=admin', 'admin_x  (created 2 days ago)']] }],
 ['restore', 'Clean and restore', 'Back to a known good state.', 'Restore files and database from a backup taken before the attack, or reinstall the core and plugins fresh. Then apply the fix for the hole before going back online.', 'Restore a clean backup|Reinstall from source|Patch before going live', 'hack', { step: 2 }],
 ['rotate', 'Rotate every secret', 'Assume everything was seen.', 'Change every password, API key, database password and token the site used, including payment gateway keys. Sign out all sessions and force users to reset passwords if their data may be exposed.', 'All passwords and keys|Log out every session|Payment keys too', 'hack', { step: 3 }],
 ['tell', 'Tell people', 'Honesty keeps trust.', 'If customer data may have leaked, tell your users clearly what happened, what data, and what they should do. In many countries the law requires it within days.', 'Say what happened|Say what to do|Follow local law', 'hack', { step: 4 }],
 ['prevent', 'Prevent the next one', 'Turn the lesson into habits.', 'Enable 2FA, automatic updates, daily off-site backups, a firewall and uptime monitoring. Review who has access every few months.', '2FA everywhere|Updates + backups|Monitoring and alerts', 'hack', { step: 5 }]
]},
{ id: 'ops', t: 'Tools & deploy', jp: '具', ic: 'git', c: '#6b604f', l: [
 ['git', 'Git basics', 'Save points for your code.', 'Git records snapshots of your project called commits. You can go back to any of them, see what changed and work on several ideas at once with branches.', 'git add + git commit|Branches for new work|Merge when ready', 'git', {}],
 ['github', 'GitHub and pull requests', 'Share code and review it.', 'GitHub hosts Git repositories online. A pull request proposes changes from a branch, so others can review, comment and run tests before it merges.', 'Push to GitHub|Open a pull request|Review, then merge', 'steps', { s: [['Branch', 'git checkout -b fix-cart'], ['Commit', 'Small, clear commits'], ['Push', 'git push origin fix-cart'], ['Pull request', 'Describe the change'], ['Review + CI', 'Tests run automatically'], ['Merge', 'Deploys to production']] }],
 ['npm', 'npm and packages', 'Other people’s code, installed in seconds.', 'npm installs JavaScript packages listed in package.json. It saves time, but every package is code you trust, so pick popular, maintained ones and keep them updated.', 'npm install name|package.json lists them|Lock file pins versions', 'term', { c: [['$ npm init -y', 'Wrote package.json'], ['$ npm install express', 'added 64 packages in 2s'], ['$ npm run dev', 'Server running on :3000']] }],
 ['terminal', 'Terminal basics', 'Talking to the computer with text.', 'The terminal runs commands: move between folders, list files, run scripts and connect to servers. A handful of commands covers most daily work.', 'cd, ls, mkdir|npm, git, ssh|Tab to autocomplete', 'term', { c: [['$ pwd', '/home/xiraiya/shop'], ['$ ls', 'index.html  package.json  src/'], ['$ mkdir assets && cd assets', ''], ['$ ssh deploy@my-server', 'Welcome to Ubuntu 24.04']] }],
 ['deploy', 'Deploying a site', 'From your laptop to the world.', 'Deploying copies your built site to a server and switches traffic to it. Modern hosts deploy automatically every time you push to the main branch.', 'Build → upload → switch|Automatic from Git|Rollback if it breaks', 'deploy', {}],
 ['ssl', 'Domains and SSL setup', 'Connect your name to your server.', 'Point your domain’s DNS A record at your server’s IP (or a CNAME at your host), then issue a free SSL certificate. Most hosts do the certificate automatically.', 'A record → IP|CNAME → host name|Auto-renewing certificate', 'url', { dns: 1 }],
 ['cicd', 'CI/CD', 'Robots that test and ship.', 'Continuous integration runs your tests on every push; continuous delivery deploys when they pass. Broken code is caught before users ever see it.', 'Tests on every push|Deploy on green|Same steps every time', 'steps', { s: [['Push', 'git push'], ['Install', 'npm ci'], ['Lint + test', '142 tests pass'], ['Build', 'Minified bundle'], ['Deploy', 'Live in 40 s']] }],
 ['docker', 'Docker', 'Ship the whole box.', 'Docker packages your app with everything it needs into a container, so it runs the same on your laptop, a teammate’s machine and the server.', 'Same everywhere|Dockerfile describes it|Easy to scale', 'code', { lang: 'docker', c: 'FROM node:22-alpine\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nCMD ["node", "server.js"]', o: 'Successfully built shop:latest' }],
 ['environments', 'Dev, staging, production', 'Break things where it is safe.', 'Develop on your machine, test on a staging copy that mirrors production, and only then release to production where real customers are.', 'Dev: your machine|Staging: a safe copy|Production: real users', 'layers', { l: [['Development', 'Your laptop, fake data'], ['Staging', 'Copy of production, test data'], ['Production', 'Real customers, real money']] }],
 ['monitoring', 'Monitoring and logs', 'Know before your customers do.', 'Uptime monitors ping your site every minute; error trackers catch exceptions; logs record what happened. Alerts on your phone mean you fix problems first.', 'Uptime checks|Error tracking|Alerts to Telegram', 'monitor', {}]
]},
{ id: 'perf', t: 'Speed & SEO', jp: '速', ic: 'zap', c: '#4d7424', l: [
 ['vitals', 'Core Web Vitals', 'Google’s speed report card.', 'LCP measures how fast the main content appears, INP how fast the page responds to taps, and CLS how much things jump around. Good scores help rankings and sales.', 'LCP < 2.5 s|INP < 200 ms|CLS < 0.1', 'vitals', {}],
 ['images', 'Image optimisation', 'Usually the biggest win.', 'Resize images to the size they are shown, use modern formats like WebP or AVIF, and compress them. A 4 MB photo can often become 120 KB with no visible difference.', 'Right size|WebP or AVIF|Compress', 'img', {}],
 ['lazy', 'Lazy loading', 'Load it when it is needed.', 'loading="lazy" tells the browser to fetch images only when they come near the screen. The first view loads faster and people who never scroll never download the rest.', 'loading="lazy"|Not for the first image|Reserve space to avoid jumps', 'motion', { demo: 'reveal' }],
 ['minify', 'Minify and bundle', 'Smaller files, fewer requests.', 'Minifying removes spaces and comments; bundling combines files; compression like Brotli shrinks them further on the wire. Tools like Vite do all three.', 'Minify|Bundle|Brotli or gzip', 'code', { lang: 'js', c: 'function addToCart(product, quantity) {\n  // add the product to the cart\n  return cart.push({ product, quantity });\n}', o: 'function a(t,n){return c.push({product:t,quantity:n})}   (−61%)' }],
 ['seo', 'SEO basics', 'Help Google understand you.', 'Clear titles, one h1, descriptive headings, fast pages, mobile-friendly layouts and real content people search for. Links from other sites build trust.', 'Unique title per page|Useful content|Fast and mobile-friendly', 'serp', {}],
 ['meta', 'Meta tags and Open Graph', 'How your link looks when shared.', 'The title and description show in Google; Open Graph tags control the preview card on Facebook, WhatsApp and Telegram. A good image and headline get more clicks.', '<title> and description|og:title, og:image|Test with a preview tool', 'og', {}],
 ['a11y', 'Accessibility', 'Websites for everyone.', 'About one in six people has a disability. Semantic HTML, alt text, keyboard support, visible focus and good contrast make your site usable by everyone, and better for SEO too.', 'Alt text|Keyboard + focus|Contrast', 'ux', { demo: 'contrast' }]
]},
{ id: 'ai', t: 'AI basics', jp: '知', ic: 'chip', c: '#7c5cff', l: [
 ['llm', 'What an LLM is', 'A model that predicts the next word, very well.', 'A large language model has read a huge amount of text and learned to predict what comes next. That simple skill, at scale, lets it write, summarise, translate and reason.', 'Predicts the next token|Trained on huge text|Can be wrong, so check it', 'tokens', {}],
 ['prompt', 'Prompts', 'How you ask matters.', 'A good prompt gives context, a clear task, the format you want and examples. Vague questions get vague answers.', 'Context + task + format|Give examples|Be specific', 'compare', { a: ['Vague', 'write something about my shop'], b: ['Clear', 'Write 3 Instagram captions (under 20 words) for a Dhaka tea shop launching iced matcha. Friendly tone.'] }],
 ['agents', 'AI agents', 'Models that use tools.', 'An agent gives an LLM tools like search, a database or email, and lets it plan steps, call tools, read results and continue until the task is done.', 'Plan → act → check|Tools give it abilities|Humans approve risky steps', 'flow', { n: ['Goal', 'Agent (LLM)', 'Tools', 'Result'], m: [[0, 1, 'refund order 4822'], [1, 2, 'db.getOrder(4822)'], [2, 1, 'paid, not shipped'], [1, 2, 'payments.refund()'], [2, 1, 'ok'], [1, 3, 'Refunded + emailed customer']] }],
 ['rag', 'RAG', 'Answers from your own documents.', 'Retrieval-augmented generation first searches your documents for relevant passages, then gives them to the model with the question. The answer is grounded in your data, not guesses.', 'Search your docs first|Give passages to the model|Fewer made-up answers', 'flow', { n: ['Question', 'Search your docs', 'LLM', 'Answer'], m: [[0, 1, 'refund policy?'], [1, 2, '3 matching passages'], [0, 2, 'question'], [2, 3, '60 days, keep the receipt']] }],
 ['embeddings', 'Embeddings', 'Meaning as coordinates.', 'An embedding turns text into a list of numbers so that similar meanings end up close together. It powers semantic search: finding “cheap laptop” when the page says “budget notebook”.', 'Text → vector|Close = similar meaning|Powers smart search', 'embed', {}]
]}
];
